                        comp.add(p)
                        stack.append(p)
        comps.append(comp)

    obj = max(comps, key=len)
    top = min(r for r, c in obj)
    bottom = max(r for r, c in obj)
    left = min(c for r, c in obj)
    right = max(c for r, c in obj)
    anchor = (top + (bottom - top) // 2, left + (right - left) // 2)

    out = [row[:] for row in grid]
